$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$api = Decode ""
$component = Decode ""

$apiPath = Join-Path $root "app\api\provider\activity-summary\route.ts"
$componentPath = Join-Path $root "app\dashboard\ProviderActivitySnapshot.tsx"
$dashboardPath = Join-Path $root "app\dashboard\ProviderDashboard.tsx"
$scorePath = Join-Path $root "lib\provider-score.ts"

foreach ($path in @($dashboardPath, $scorePath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.02 : fichier requis introuvable : $path"
    }
}

$score = [System.IO.File]::ReadAllText($scorePath)

if (-not $score.Contains("KLYX_GROUP_AWARE_PROVIDER_SCORE_13_00")) {
    throw "13.02 : KLYX 13.00 introuvable."
}

New-Item -ItemType Directory -Force -Path (Split-Path -Parent $apiPath) | Out-Null

[System.IO.File]::WriteAllText($apiPath, $api, $utf8)
[System.IO.File]::WriteAllText($componentPath, $component, $utf8)

$dashboard = [System.IO.File]::ReadAllText($dashboardPath)

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
Copy-Item -LiteralPath $dashboardPath -Destination ($dashboardPath + ".bak-13-02-" + $timestamp) -Force

if (-not $dashboard.Contains("ProviderActivitySnapshot")) {
    $importAnchor = 'import DashboardActionCenter from "@/app/components/DashboardActionCenter";'

    if (-not $dashboard.Contains($importAnchor)) {
        throw "13.02 : import DashboardActionCenter introuvable."
    }

    $newImport = $importAnchor + "`r`n" + 'import ProviderActivitySnapshot from "./ProviderActivitySnapshot";'

    $dashboard = $dashboard.Replace($importAnchor, $newImport)
}

if (-not $dashboard.Contains("KLYX_PROVIDER_ACTIVITY_DASHBOARD_13_02")) {
    $anchor = '      <DashboardActionCenter accountType="provider" />'

    if (-not $dashboard.Contains($anchor)) {
        throw "13.02 : DashboardActionCenter JSX introuvable."
    }

    $replacement = $anchor + "`r`n`r`n" + '      {/* KLYX_PROVIDER_ACTIVITY_DASHBOARD_13_02 */}' + "`r`n" + '      <ProviderActivitySnapshot />'

    $dashboard = $dashboard.Replace($anchor, $replacement)
}

[System.IO.File]::WriteAllText($dashboardPath, $dashboard, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.02 APPLIQUE"
Write-Host "======================================"
Write-Host "Dashboard group-aware : AJOUTE"
Write-Host "Mission groupee = 1 : OK"
Write-Host "Volume slots = N : OK"
Write-Host "API lecture seule : OK"
Write-Host "Finance/Stripe : INCHANGES"
Write-Host "======================================"
